import { useNavigate } from "react-router-dom";
import "./HomePage.css";

function HomePage() {

  const navigate = useNavigate();

  return (

    <div className="home-container">

      <div className="home-card">

        <h1>
          🏥 Smart Queue System
        </h1>

        <p>
          Hospital Queue Management
        </p>

        <button
          className="login-btn"

          onClick={() =>
            navigate("/login")
          }
        >

          Login

        </button>


        <button
          className="admin-btn"

          onClick={() =>
            navigate("/admin")
          }
        >

          Admin Dashboard

        </button>

      </div>

    </div>

  );

}

export default HomePage;
